import{_ as t,o as a,c as o,a0 as i}from"./chunks/framework.Ckbw5VQO.js";const p=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"about/contributing.md","filePath":"about/contributing.md"}'),n={name:"about/contributing.md"};function r(s,e,d,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><h2 id="submission-guidelines" tabindex="-1">Submission guidelines <a class="header-anchor" href="#submission-guidelines" aria-label="Permalink to &quot;Submission guidelines&quot;">​</a></h2><p>Contributions are always welcome!</p><p>Contributions are what make the open-source community such an amazing place to learn, inspire, and create. Any contributions you make are <strong>greatly appreciated</strong>.</p><p>If you have a suggestion that would make this better, please fork the repo and create a pull request. You can also simply open an issue with the tag <code>enhancement</code>.</p><ol><li>Fork the repository.</li><li>Create your feature branch: <code>git checkout -b feature/my-feature</code></li><li>Commit your changes: <code>git commit -m &quot;feat: add some feature&quot;</code></li><li>Push to the branch: <code>git push origin feature/my-feature</code></li><li>Submit a pull request.</li></ol><h2 id="commit-message-guidelines" tabindex="-1">Commit message guidelines <a class="header-anchor" href="#commit-message-guidelines" aria-label="Permalink to &quot;Commit message guidelines&quot;">​</a></h2><p>We follow the <a href="https://www.conventionalcommits.org/en/v1.0.0-beta.3/" target="_blank" rel="noreferrer">Conventional commits</a> specification, which keeps the history readable and lets us generate the changelog automatically.</p><h3 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;type&gt;: &lt;subject&gt; [optional `breaking`]</span></span></code></pre></div><p><code>type</code> must be one of the following:</p><table tabindex="0"><thead><tr><th>Type</th><th>When to use</th></tr></thead><tbody><tr><td><code>build</code></td><td>Changes affecting the build system (external dependencies)</td></tr><tr><td><code>ci</code></td><td>Changes to the CI configuration</td></tr><tr><td><code>chore</code></td><td>Changes affecting the project structure</td></tr><tr><td><code>docs</code></td><td>Documentation-only changes</td></tr><tr><td><code>feat</code></td><td>A new feature</td></tr><tr><td><code>fix</code></td><td>A bug fix</td></tr><tr><td><code>perf</code></td><td>A performance improvement</td></tr><tr><td><code>refactor</code></td><td>Code change that neither fixes a bug nor adds a feature</td></tr><tr><td><code>revert</code></td><td>Revert a previous commit</td></tr><tr><td><code>style</code></td><td>Formatting (lint, whitespace)</td></tr><tr><td><code>test</code></td><td>Adding or fixing tests</td></tr></tbody></table><p>The optional <code>[ breaking ]</code> keyword declares a <strong>BREAKING CHANGE</strong>.</p><h3 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feat: allow provided config object to extend other configs [ breaking ]</span></span>\n<span class="line"><span>docs: correct spelling in the contributing.md file</span></span>\n<span class="line"><span>fix: fix minor issue in code (#12)</span></span></code></pre></div>',15)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
